// PO-S07: prints the SQL that Sequelize runs for the queries touched by an edit of point 1(b)
// (where: null left out, a nested include given as an array, silent removed from upsert).
// Run on the compiled server before and after a conversion; the two outputs must be identical.
// Usage: node sqlcapture.js <repo root>
//
// In this folder:
//   sql-capture-before.txt  taken at commit 265b6757, when Collection, PlaybackSession, Playlist, User and LibraryItem were all still JavaScript
//   sql-capture-after.txt   taken at the end of the run (Collection, PlaybackSession, Playlist and User converted; LibraryItem skipped and restored)
// The capture was also repeated after each of the four conversions; every time it was identical to the "before" file.
// The LibraryItem calls are in the script because its edits were tried in the skipped pass; in both files they run the unchanged LibraryItem.js.
const path = require('path')
const root = process.argv[2]
const { Sequelize } = require(path.join(root, 'node_modules/sequelize'))
const Database = require(path.join(root, 'dist-server/server/Database'))
const Logger = require(path.join(root, 'dist-server/server/Logger'))

async function main() {
  const lines = []
  Logger.error = () => {}
  Logger.debug = () => {}
  global.ServerSettings = {}
  Database.sequelize = new Sequelize({ dialect: 'sqlite', storage: ':memory:', logging: (sql) => lines.push(sql) })
  Database.sequelize.uppercaseFirst = (str) => (str ? `${str[0].toUpperCase()}${str.substr(1)}` : '')
  await Database.buildModels()

  const fixedDate = new Date('2026-01-02T03:04:05.000Z')
  const user = await Database.userModel.create({ id: '11111111-1111-4111-8111-111111111111', username: 'u', type: 'user', isActive: true, permissions: {}, createdAt: fixedDate, updatedAt: fixedDate })
  const library = await Database.libraryModel.create({ id: '22222222-2222-4222-8222-222222222222', name: 'L', mediaType: 'book', createdAt: fixedDate, updatedAt: fixedDate })
  const playlist = await Database.playlistModel.create({ id: '33333333-3333-4333-8333-333333333333', name: 'P', libraryId: library.id, userId: user.id, createdAt: fixedDate, updatedAt: fixedDate })
  user.mediaProgresses = []

  lines.length = 0
  const run = async (label, fn) => {
    lines.push(`## ${label}`)
    try {
      await fn()
    } catch (error) {
      lines.push(`THREW ${error.name}: ${error.message}`)
    }
  }

  await run('Collection.getOldCollectionsJsonExpanded(null) [where is null]', () => Database.collectionModel.getOldCollectionsJsonExpanded(null))
  await run('Collection.getOldCollectionsJsonExpanded(null, libraryId, [rssfeed])', () => Database.collectionModel.getOldCollectionsJsonExpanded(null, library.id, ['rssfeed']))

  await run('PlaybackSession.getOldPlaybackSessions() [where is null]', () => Database.playbackSessionModel.getOldPlaybackSessions())
  await run('PlaybackSession.getOldPlaybackSessions({ userId })', () => Database.playbackSessionModel.getOldPlaybackSessions({ userId: user.id }))
  const oldSession = {
    id: '44444444-4444-4444-8444-444444444444',
    userId: user.id,
    libraryId: library.id,
    libraryItemId: 'li-1',
    bookId: '55555555-5555-4555-8555-555555555555',
    episodeId: null,
    displayTitle: 'T',
    displayAuthor: 'A',
    duration: 10,
    playMethod: 0,
    mediaPlayer: 'html5',
    startTime: 0,
    currentTime: 5,
    serverVersion: '2.37.0',
    startedAt: fixedDate.valueOf(),
    updatedAt: fixedDate.valueOf(),
    deviceInfo: null,
    timeListening: 5,
    coverPath: null,
    mediaMetadata: { title: 'T' },
    date: '2026-01-02',
    dayOfWeek: 'Friday'
  }
  await run('PlaybackSession.createFromOld(session) [upsert, first time]', () => Database.playbackSessionModel.createFromOld(oldSession))
  await run('PlaybackSession.createFromOld(session) [upsert, second time]', () => Database.playbackSessionModel.createFromOld({ ...oldSession, currentTime: 6 }))
  await run('PlaybackSession row after the two upserts', async () => {
    const [rows] = await Database.sequelize.query('SELECT * FROM playbackSessions', { logging: false })
    lines.push(`ROWS ${JSON.stringify(rows)}`)
  })

  await run('Playlist.getOldPlaylistsForUserAndLibrary(userId, libraryId)', () => Database.playlistModel.getOldPlaylistsForUserAndLibrary(user.id, library.id))
  await run('Playlist.getPlaylistsForMediaItemIds([id])', () => Database.playlistModel.getPlaylistsForMediaItemIds(['66666666-6666-4666-8666-666666666666']))
  await run('playlist.getMediaItemsExpandedWithLibraryItem()', () => playlist.getMediaItemsExpandedWithLibraryItem())

  await run('user.createUpdateMediaProgressFromPayload({ episodeId })', () => user.createUpdateMediaProgressFromPayload({ episodeId: '77777777-7777-4777-8777-777777777777', libraryItemId: 'li-1' }))
  await run('user.createUpdateMediaProgressFromPayload({ libraryItemId })', () => user.createUpdateMediaProgressFromPayload({ libraryItemId: '88888888-8888-4888-8888-888888888888' }))

  await run('LibraryItem.getLibraryItemsIncrement(0, 10) [where is null]', () => Database.libraryItemModel.getLibraryItemsIncrement(0, 10))
  await run('LibraryItem.getLibraryItemsIncrement(0, 10, { libraryId })', () => Database.libraryItemModel.getLibraryItemsIncrement(0, 10, { libraryId: library.id }))
  await run('LibraryItem.findAllExpandedWhere() [where is null]', () => Database.libraryItemModel.findAllExpandedWhere())
  await run('LibraryItem.findAllExpandedWhere({ libraryId })', () => Database.libraryItemModel.findAllExpandedWhere({ libraryId: library.id }))
  await run('LibraryItem.findOneExpanded({ id }) [replacements and include are null]', () => Database.libraryItemModel.findOneExpanded({ id: '99999999-9999-4999-8999-999999999999' }))
  await run('LibraryItem.findOneExpanded({ mediaId }, null, { model: library })', () => Database.libraryItemModel.findOneExpanded({ mediaId: '99999999-9999-4999-8999-999999999999' }, null, { model: Database.libraryModel, attributes: ['settings'] }))
  await run('LibraryItem.getExpandedById(id)', () => Database.libraryItemModel.getExpandedById('99999999-9999-4999-8999-999999999999'))

  console.log(lines.join('\n'))
}

main().catch((error) => {
  console.error('sqlcapture failed', error)
  process.exit(1)
})

// PO-S07 probe for the reported bug in Book.ts (lines 517-519 and 552 of the old Book.js; Book.ts:651-653 and 686 now):
//   bookSeries.sequence is read without the ?. guard used elsewhere.
// Question: what does the current code do when a series is loaded without its join row, and does the code say what it should do?
// This file is NOT part of the test suite. It is run from outside the repo against the compiled server.
// Usage: REPO_ROOT=<repo> npx mocha <this file>
const path = require('path')
const root = process.env.REPO_ROOT
const { expect } = require(path.join(root, 'node_modules/chai'))
const { Sequelize } = require(path.join(root, 'node_modules/sequelize'))
const Database = require(path.join(root, 'dist-server/server/Database'))

describe('PROBE Book and a series loaded without its bookSeries join row (current code, no fix)', () => {
  let bookId
  let libraryId

  /**
   * @param {string[]} throughAttributes attributes of the join row to load; [] loads no join row
   */
  function loadBook(throughAttributes) {
    return Database.bookModel.findByPk(bookId, {
      include: [
        { model: Database.authorModel, through: { attributes: [] } },
        { model: Database.seriesModel, through: { attributes: throughAttributes } }
      ]
    })
  }

  beforeEach(async () => {
    global.ServerSettings = {}
    Database.sequelize = new Sequelize({ dialect: 'sqlite', storage: ':memory:', logging: false })
    Database.sequelize.uppercaseFirst = (str) => (str ? `${str[0].toUpperCase()}${str.substr(1)}` : '')
    await Database.buildModels()

    const library = await Database.libraryModel.create({ name: 'Books', mediaType: 'book' })
    libraryId = library.id
    const book = await Database.bookModel.create({ title: 'Test Book', audioFiles: [], tags: [], narrators: [], genres: [], chapters: [] })
    bookId = book.id
    const series = await Database.seriesModel.create({ name: 'Test Series', libraryId })
    await Database.bookSeriesModel.create({ bookId, seriesId: series.id, sequence: '2' })
  })

  afterEach(async () => {
    await Database.sequelize.sync({ force: true })
  })

  it('with the join row loaded (the include of every expanded query): the old metadata has the sequence', async () => {
    const book = await loadBook(['sequence'])
    expect(book.series[0].bookSeries.sequence).to.equal('2')
    expect(book.oldMetadataToJSON().series).to.deep.equal([{ id: book.series[0].id, name: 'Test Series', sequence: '2' }])
  })

  it('without the join row (through: { attributes: [] }): series[0].bookSeries is undefined', async () => {
    const book = await loadBook([])
    expect(book.series).to.have.lengthOf(1)
    expect(book.series[0].bookSeries).to.be.undefined
  })

  it('without the join row: the guarded reads work and report the series as having no sequence', async () => {
    const book = await loadBook([])
    expect(book.seriesName).to.equal('Test Series')
    expect(book.oldMetadataToJSONMinified().seriesName).to.equal('Test Series')
    expect(book.getAbsMetadataJson().series).to.deep.equal(['Test Series'])
  })

  it('without the join row: oldMetadataToJSON() throws a TypeError (Book.ts:686, the reported line)', async () => {
    const book = await loadBook([])
    expect(() => book.oldMetadataToJSON()).to.throw(TypeError, "Cannot read properties of undefined (reading 'sequence')")
  })

  it('without the join row: updateSeriesFromRequest() rejects with a TypeError (Book.ts:651, the other reported lines)', async () => {
    const book = await loadBook([])
    let error = null
    try {
      await book.updateSeriesFromRequest([{ name: 'Test Series', sequence: '3' }], libraryId)
    } catch (err) {
      error = err
    }
    expect(error).to.be.instanceOf(TypeError)
    expect(error.message).to.equal("Cannot read properties of undefined (reading 'sequence')")
  })

  it('for comparison: toOldJSON() throws on purpose when a required include is missing', async () => {
    const book = await Database.bookModel.findByPk(bookId)
    expect(() => book.toOldJSON('some-library-item-id')).to.throw('[Book] Cannot convert to old JSON because authors are not loaded')
  })
})

import sequelizeModule = require('sequelize')
const { DataTypes, Model } = sequelizeModule
import type { BuildOptions, CreationAttributes, Sequelize } from 'sequelize'
import Logger = require('../Logger')

type LibraryFolder = import('./LibraryFolder')

// Type-only: keeps import('../models/Library').LibrarySettingsObject (used by the scanners) resolvable after export = Library
declare namespace Library {
  // The typedef lists every key as required. The keys marked optional are the ones getDefaultLibrarySettingsForMediaType() leaves out for one of the two media types;
  // epubsAllowScriptedContent and podcastSearchRegion are set there but missing from the typedef; the two null defaults are typed as nullable.
  interface LibrarySettingsObject {
    coverAspectRatio: number
    disableWatcher: boolean
    skipMatchingMediaWithAsin?: boolean
    skipMatchingMediaWithIsbn?: boolean
    autoScanCronExpression: string | null
    audiobooksOnly?: boolean
    epubsAllowScriptedContent?: boolean
    hideSingleBookSeries?: boolean
    onlyShowLaterBooksInContinueSeries?: boolean
    metadataPrecedence?: string[]
    podcastSearchRegion?: string
    markAsFinishedTimeRemaining: number
    markAsFinishedPercentComplete: number | null
  }
}
type LibrarySettingsObject = Library.LibrarySettingsObject

/**
 * @typedef LibrarySettingsObject
 * @property {number} coverAspectRatio BookCoverAspectRatio
 * @property {boolean} disableWatcher
 * @property {boolean} skipMatchingMediaWithAsin
 * @property {boolean} skipMatchingMediaWithIsbn
 * @property {string} autoScanCronExpression
 * @property {boolean} audiobooksOnly
 * @property {boolean} hideSingleBookSeries Do not show series that only have 1 book
 * @property {boolean} onlyShowLaterBooksInContinueSeries Skip showing books that are earlier than the max sequence read
 * @property {string[]} metadataPrecedence
 * @property {number} markAsFinishedTimeRemaining Time remaining in seconds to mark as finished. (defaults to 10s)
 * @property {number} markAsFinishedPercentComplete Percent complete to mark as finished (0-100). If this is set it will be used over markAsFinishedTimeRemaining.
 */

class Library extends Model {
  declare id: string
  declare name: string
  declare displayOrder: number
  declare icon: string
  declare mediaType: string
  declare provider: string
  declare lastScan: Date | null // null until the first scan (toOldJSON() reads it with ?.); the JSDoc says Date
  declare lastScanVersion: string
  declare settings: LibrarySettingsObject
  declare extraData: { lastScanMetadataPrecedence?: string[] } | null // the JSDoc says Object; lastScanMetadataPrecedence is the only key this file reads, and it reads it with ?.
  declare createdAt: Date
  declare updatedAt: Date
  declare libraryFolders?: LibraryFolder[]
  declare static readonly sequelize: Sequelize // set by init() before any query runs (optional in Sequelize's typings)

  constructor(values?: CreationAttributes<Library>, options?: BuildOptions) {
    super(values, options)

    /** @type {UUIDV4} */
    this.id
    /** @type {string} */
    this.name
    /** @type {number} */
    this.displayOrder
    /** @type {string} */
    this.icon
    /** @type {string} */
    this.mediaType
    /** @type {string} */
    this.provider
    /** @type {Date} */
    this.lastScan
    /** @type {string} */
    this.lastScanVersion
    /** @type {LibrarySettingsObject} */
    this.settings
    /** @type {Object} */
    this.extraData
    /** @type {Date} */
    this.createdAt
    /** @type {Date} */
    this.updatedAt
    /** @type {import('./LibraryFolder')[]|undefined} */
    this.libraryFolders
  }

  /**
   *
   * @param {string} mediaType
   * @returns
   */
  static getDefaultLibrarySettingsForMediaType(mediaType: string) {
    if (mediaType === 'podcast') {
      return {
        coverAspectRatio: 1, // Square
        disableWatcher: false,
        autoScanCronExpression: null,
        podcastSearchRegion: 'us',
        markAsFinishedPercentComplete: null,
        markAsFinishedTimeRemaining: 10
      }
    } else {
      return {
        coverAspectRatio: 1, // Square
        disableWatcher: false,
        autoScanCronExpression: null,
        skipMatchingMediaWithAsin: false,
        skipMatchingMediaWithIsbn: false,
        audiobooksOnly: false,
        epubsAllowScriptedContent: false,
        hideSingleBookSeries: false,
        onlyShowLaterBooksInContinueSeries: false,
        metadataPrecedence: this.defaultMetadataPrecedence,
        markAsFinishedPercentComplete: null,
        markAsFinishedTimeRemaining: 10
      }
    }
  }

  static get defaultMetadataPrecedence() {
    return ['folderStructure', 'audioMetatags', 'nfoFile', 'txtFiles', 'opfFile', 'absMetadata']
  }

  /**
   *
   * @returns {Promise<Library[]>}
   */
  static getAllWithFolders() {
    return this.findAll({
      include: this.sequelize.models.libraryFolder,
      order: [['displayOrder', 'ASC']]
    })
  }

  /**
   *
   * @param {string} libraryId
   * @returns {Promise<Library>}
   */
  static findByIdWithFolders(libraryId: string) {
    return this.findByPk(libraryId, {
      include: this.sequelize.models.libraryFolder
    })
  }

  /**
   * Get all library ids
   * @returns {Promise<string[]>} array of library ids
   */
  static async getAllLibraryIds() {
    const libraries = await this.findAll({
      attributes: ['id', 'displayOrder'],
      order: [['displayOrder', 'ASC']]
    })
    return libraries.map((l) => l.id)
  }

  /**
   * Get the largest value in the displayOrder column
   * Used for setting a new libraries display order
   * @returns {Promise<number>}
   */
  static async getMaxDisplayOrder() {
    return (await this.max<number, Library>('displayOrder')) || 0
  }

  /**
   * Updates displayOrder to be sequential
   * Used after removing a library
   */
  static async resetDisplayOrder() {
    const libraries = await this.findAll({
      order: [['displayOrder', 'ASC']]
    })
    for (let i = 0; i < libraries.length; i++) {
      const library = libraries[i]
      if (library.displayOrder !== i + 1) {
        Logger.debug(`[Library] Updating display order of library from ${library.displayOrder} to ${i + 1}`)
        await library.update({ displayOrder: i + 1 }).catch((error) => {
          Logger.error(`[Library] Failed to update library display order to ${i + 1}`, error)
        })
      }
    }
  }

  static init(this: never, ...args: never[]): never // uncallable: keeps the static side assignable to Model.init, which this method replaces
  static init(sequelize: Sequelize): void
  /**
   * Initialize model
   * @param {import('../Database').sequelize} sequelize
   */
  static init(sequelize: Sequelize): void {
    super.init(
      {
        id: {
          type: DataTypes.UUID,
          defaultValue: DataTypes.UUIDV4,
          primaryKey: true
        },
        name: DataTypes.STRING,
        displayOrder: DataTypes.INTEGER,
        icon: DataTypes.STRING,
        mediaType: DataTypes.STRING,
        provider: DataTypes.STRING,
        lastScan: DataTypes.DATE,
        lastScanVersion: DataTypes.STRING,
        settings: DataTypes.JSON,
        extraData: DataTypes.JSON
      },
      {
        sequelize,
        modelName: 'library'
      }
    )
  }

  get isPodcast() {
    return this.mediaType === 'podcast'
  }
  get isBook() {
    return this.mediaType === 'book'
  }
  /**
   * @returns {string[]}
   */
  get lastScanMetadataPrecedence() {
    return this.extraData?.lastScanMetadataPrecedence || []
  }

  /**
   * @returns {LibrarySettingsObject}
   */
  get librarySettings(): LibrarySettingsObject {
    return this.settings || Library.getDefaultLibrarySettingsForMediaType(this.mediaType)
  }

  /**
   * TODO: Update to use new model
   */
  toOldJSON() {
    return {
      id: this.id,
      name: this.name,
      folders: (this.libraryFolders || []).map((f) => f.toOldJSON()),
      displayOrder: this.displayOrder,
      icon: this.icon,
      mediaType: this.mediaType,
      provider: this.provider,
      settings: {
        ...this.settings
      },
      lastScan: this.lastScan?.valueOf() || null,
      lastScanVersion: this.lastScanVersion,
      createdAt: this.createdAt.valueOf(),
      lastUpdate: this.updatedAt.valueOf()
    }
  }
}

export = Library

const { expect } = require('chai')
const { Sequelize } = require('sequelize')

const Database = require('../../../server/Database')

describe('Library.getMaxDisplayOrder', () => {
  beforeEach(async () => {
    global.ServerSettings = {}
    Database.sequelize = new Sequelize({ dialect: 'sqlite', storage: ':memory:', logging: false })
    Database.sequelize.uppercaseFirst = (str) => (str ? `${str[0].toUpperCase()}${str.substr(1)}` : '')
    await Database.buildModels()
  })

  afterEach(async () => {
    await Database.sequelize.sync({ force: true })
  })

  it('returns the largest display order of the libraries', async () => {
    await Database.libraryModel.create({ name: 'First', mediaType: 'book', displayOrder: 1 })
    await Database.libraryModel.create({ name: 'Third', mediaType: 'podcast', displayOrder: 3 })

    expect(await Database.libraryModel.getMaxDisplayOrder()).to.equal(3)
  })

  it('returns 0 when there is no library', async () => {
    expect(await Database.libraryModel.getMaxDisplayOrder()).to.equal(0)
  })
})
